import{_ as e,c as r,o as n,a0 as t}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Introduksjon til mentalt spill – slides for veileder","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/no/facilitator-slides.md","filePath":"public/downloads/no/facilitator-slides.md"}');const a=e({name:"public/downloads/no/facilitator-slides.md"},[["render",function(e,i,a,l,s,o){return n(),r("div",null,[...i[0]||(i[0]=[t('<h1 id="introduksjon-til-mentalt-spill-–-slides-for-veileder" tabindex="-1">Introduksjon til mentalt spill – slides for veileder <a class="header-anchor" href="#introduksjon-til-mentalt-spill-–-slides-for-veileder" aria-label="Permalink to &quot;Introduksjon til mentalt spill – slides for veileder&quot;">​</a></h1><p><strong>Petanque-akademiet</strong><em>Øktguide for tilretteleggere</em></p><hr><h2 id="lysbilde-1-velkommen" tabindex="-1">Lysbilde 1: Velkommen <a class="header-anchor" href="#lysbilde-1-velkommen" aria-label="Permalink to &quot;Lysbilde 1: Velkommen&quot;">​</a></h2><h1 id="🎯-introduksjon-til-mentalt-spill" tabindex="-1">🎯 Introduksjon til mentalt spill <a class="header-anchor" href="#🎯-introduksjon-til-mentalt-spill" aria-label="Permalink to &quot;🎯 Introduksjon til mentalt spill&quot;">​</a></h1><p><strong>For Elite Petanque-spillere</strong></p><h3 id="i-dag-vil-du-oppdage" tabindex="-1">I dag vil du oppdage: <a class="header-anchor" href="#i-dag-vil-du-oppdage" aria-label="Permalink to &quot;I dag vil du oppdage:&quot;">​</a></h3><ul><li>🧠 Hvordan skape de rette forholdene for «sonen»</li><li>💪 Hvordan stilne din indre kritiker</li><li>🎪 Praktiske verktøy som fungerer under press</li></ul><p><strong>Gjør deg klar for en interaktiv økt!</strong></p><hr><h2 id="lysbilde-2-rask-avstemning-–-rekk-opp-hendene-🙋" tabindex="-1">Lysbilde 2: Rask avstemning – Rekk opp hendene! 🙋 <a class="header-anchor" href="#lysbilde-2-rask-avstemning-–-rekk-opp-hendene-🙋" aria-label="Permalink to &quot;Lysbilde 2: Rask avstemning – Rekk opp hendene! 🙋&quot;">​</a></h2><h3 id="hvem-har-opplevd-dette" tabindex="-1">Hvem har opplevd dette? <a class="header-anchor" href="#hvem-har-opplevd-dette" aria-label="Permalink to &quot;Hvem har opplevd dette?&quot;">​</a></h3><p><strong>Rekk opp hånden hvis du noen gang har:</strong></p><ol><li><p>Trente du et perfekt skudd på trening... og så bommet du på det i konkurransen? 🎯❌</p></li><li><p>Kjente du at tankene dine raste da du trengte å holde deg rolig? 🧠💨</p></li><li><p>Kritisert deg selv etter en feil? 😤</p></li><li><p>Hadde du et spill der alt bare «klikket»? ✨</p></li></ol><p><strong>Du er ikke alene! La oss fikse dette sammen.</strong></p><hr><h2 id="lysbilde-3-elitespillerparadokset" tabindex="-1">Lysbilde 3: Elitespillerparadokset <a class="header-anchor" href="#lysbilde-3-elitespillerparadokset" aria-label="Permalink to &quot;Lysbilde 3: Elitespillerparadokset&quot;">​</a></h2><h3 id="du-har-allerede-ferdighetene-sa-hvorfor" tabindex="-1">Du har allerede ferdighetene ... så hvorfor? <a class="header-anchor" href="#du-har-allerede-ferdighetene-sa-hvorfor" aria-label="Permalink to &quot;Du har allerede ferdighetene ... så hvorfor?&quot;">​</a></h3><p><strong>✅ Du HAR:</strong></p><ul><li>Utmerket teknikk (tusenvis av timer)</li><li>Årelang erfaring</li><li>Fysisk evne</li></ul><p><strong>❌ Men du SLØSER med:</strong></p><ul><li>Tilgang til den teknikken under press</li><li>Å holde seg konsekvent i konkurransen</li><li>Å komme tilbake etter feil</li></ul><h3 id="den-manglende-brikken-🧩" tabindex="-1">Den manglende brikken? 🧩 <a class="header-anchor" href="#den-manglende-brikken-🧩" aria-label="Permalink to &quot;Den manglende brikken? 🧩&quot;">​</a></h3><p><strong>Ditt mentale spill.</strong></p><p><em>&quot;Forskjellen mellom godt og flott er det som skjer mellom ørene dine.&quot;</em></p><hr><h2 id="lysbilde-4-sonen-–-du-kjenner-denne-følelsen-⚡" tabindex="-1">Lysbilde 4: Sonen – Du kjenner denne følelsen! ⚡ <a class="header-anchor" href="#lysbilde-4-sonen-–-du-kjenner-denne-følelsen-⚡" aria-label="Permalink to &quot;Lysbilde 4: Sonen – Du kjenner denne følelsen! ⚡&quot;">​</a></h2><h3 id="husker-du-det-perfekte-spillet" tabindex="-1">Husker du det perfekte spillet? <a class="header-anchor" href="#husker-du-det-perfekte-spillet" aria-label="Permalink to &quot;Husker du det perfekte spillet?&quot;">​</a></h3><p><strong>Alt føltes:</strong></p><ul><li>⏱️ Tiden gikk saktere</li><li>🎯 Uanstrengt og automatisk</li><li>🧘 Fullstendig fokusert</li><li>🎪 Som om du ikke kunne gå glipp av det</li></ul><h3 id="det-er-«sonen»-flyttilstanden" tabindex="-1">Det er «sonen» (flyttilstanden) <a class="header-anchor" href="#det-er-«sonen»-flyttilstanden" aria-label="Permalink to &quot;Det er «sonen» (flyttilstanden)&quot;">​</a></h3><p><strong>Spørsmålet:</strong><em>Hvordan får vi tilgang til det konsekvent, ikke bare ved et uhell?</em></p><p><strong>Svaret:</strong><em>Forstår dine to tankemåter...</em></p><hr><h2 id="lysbilde-5-hjernen-din-har-to-moduser-🧠" tabindex="-1">Lysbilde 5: Hjernen din har to moduser 🧠 <a class="header-anchor" href="#lysbilde-5-hjernen-din-har-to-moduser-🧠" aria-label="Permalink to &quot;Lysbilde 5: Hjernen din har to moduser 🧠&quot;">​</a></h2><h3 id="🤔-planleggingsmodus-analytisk-hjerne" tabindex="-1">🤔 PLANLEGGINGSMODUS (Analytisk hjerne) <a class="header-anchor" href="#🤔-planleggingsmodus-analytisk-hjerne" aria-label="Permalink to &quot;🤔 PLANLEGGINGSMODUS (Analytisk hjerne)&quot;">​</a></h3><p><strong>Når det skal brukes:</strong> FØR injeksjonen</p><ul><li>📊 Analyserer terrenget</li><li>🎯 Velge strategi</li><li>⚖️ Veiing av risikoene</li><li>🤝 Bestemmer skuddet</li></ul><h3 id="🎯-utførelsesmodus-flow-brain" tabindex="-1">🎯 UTFØRELSESMODUS (Flow Brain) <a class="header-anchor" href="#🎯-utførelsesmodus-flow-brain" aria-label="Permalink to &quot;🎯 UTFØRELSESMODUS (Flow Brain)&quot;">​</a></h3><p><strong>Når det skal brukes:</strong> UNDER injeksjonen</p><ul><li>💪 Stol på kroppen din</li><li>🚫 Tenker IKKE på teknikk</li><li>⏰ Kun nåtiden</li><li>🤖 Automatisk ytelse</li></ul><h3 id="⚠️-problemet" tabindex="-1">⚠️ PROBLEMET: <a class="header-anchor" href="#⚠️-problemet" aria-label="Permalink to &quot;⚠️ PROBLEMET:&quot;">​</a></h3><p><strong>De fleste spillerne holder seg i planleggingsmodus under utførelse!</strong><em>Din analytiske hjerne forstyrrer din automatiske ytelse.</em></p><hr><h2 id="lysbilde-6-bryteren-–-ditt-hemmelige-vapen-🔄" tabindex="-1">Lysbilde 6: Bryteren – Ditt hemmelige våpen 🔄 <a class="header-anchor" href="#lysbilde-6-bryteren-–-ditt-hemmelige-vapen-🔄" aria-label="Permalink to &quot;Lysbilde 6: Bryteren – Ditt hemmelige våpen 🔄&quot;">​</a></h2><h3 id="mestre-denne-ene-ferdigheten" tabindex="-1">Mestre denne ene ferdigheten: <a class="header-anchor" href="#mestre-denne-ene-ferdigheten" aria-label="Permalink to &quot;Mestre denne ene ferdigheten:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="prosessen" tabindex="-1">Prosessen: <a class="header-anchor" href="#prosessen" aria-label="Permalink to &quot;Prosessen:&quot;">​</a></h3><p><strong>1️⃣ FØR (10–15 sekunder):</strong></p><ul><li>🤔 Analyser alt</li><li>📊 Planlegg strategien din</li><li>✅ Ta din avgjørelse</li></ul><p><strong>2️⃣ BYTTET (3 åndedrag):</strong></p><ul><li>🌬️ Pust dypt</li><li>🧘 Få orden på tankene dine</li><li>🔄 Slipp analysen</li></ul><p><strong>3️⃣ I LØPET AV (2–3 sekunder):</strong></p><ul><li>🎯 Stol fullt og helt på</li><li>🤖 La det skje</li><li>⚡ Utfør automatisk</li></ul><p><strong>Øv på denne bryteren = Tilgangsflyt på forespørsel!</strong></p><hr><h2 id="lysbilde-7-aktivitet-–-prøv-det-na-🎯" tabindex="-1">Lysbilde 7: AKTIVITET – Prøv det nå! 🎯 <a class="header-anchor" href="#lysbilde-7-aktivitet-–-prøv-det-na-🎯" aria-label="Permalink to &quot;Lysbilde 7: AKTIVITET – Prøv det nå! 🎯&quot;">​</a></h2><h3 id="la-oss-øve-pa-bryteren-2-minutter" tabindex="-1">La oss øve på bryteren (2 minutter) <a class="header-anchor" href="#la-oss-øve-pa-bryteren-2-minutter" aria-label="Permalink to &quot;La oss øve på bryteren (2 minutter)&quot;">​</a></h3><p><strong>Alle sammen reiser seg!</strong></p><ol><li><p><strong>Planleggingsmodus (10 sek):</strong> Tenk deg å analysere et skudd. Tenk på terreng, strategi og risikoer.</p></li><li><p><strong>Bryteren (3 åndedrag):</strong> Ta tre dype åndedrag. Klar tankene dine med hvert utpust.</p></li><li><p><strong>Utførelsesmodus (3 sek):</strong> Tenk deg å kaste. Ingen tenking. Bare stol på og flyt.</p></li></ol><p><strong>Hvordan føltes det? Annerledes?</strong></p><p><em>Sett deg ned, så snakker vi...</em></p><hr><h2 id="lysbilde-8-møt-din-indre-kritiker-😈" tabindex="-1">Lysbilde 8: Møt din indre kritiker 😈 <a class="header-anchor" href="#lysbilde-8-møt-din-indre-kritiker-😈" aria-label="Permalink to &quot;Lysbilde 8: Møt din indre kritiker 😈&quot;">​</a></h2><h3 id="høres-denne-stemmen-kjent-ut" tabindex="-1">Høres denne stemmen kjent ut? <a class="header-anchor" href="#høres-denne-stemmen-kjent-ut" aria-label="Permalink to &quot;Høres denne stemmen kjent ut?&quot;">​</a></h3><p><strong>Etter et dårlig skudd:</strong></p><ul><li>💢 &quot;Det var FORFERDELIG!&quot;</li><li>😤 &quot;Du roter ALLTID det til under press!&quot;</li><li>😰 «Alle ser på at du mislykkes!»</li><li>😞 «Du er bare ikke god nok!»</li></ul><h3 id="rask-avstemning-🙋" tabindex="-1">Rask avstemning: 🙋 <a class="header-anchor" href="#rask-avstemning-🙋" aria-label="Permalink to &quot;Rask avstemning: 🙋&quot;">​</a></h3><p><strong>Hvem hører denne stemmen regelmessig?</strong></p><h3 id="sannheten" tabindex="-1">Sannheten: <a class="header-anchor" href="#sannheten" aria-label="Permalink to &quot;Sannheten:&quot;">​</a></h3><p><strong>Din indre kritiker prøver å hjelpe...</strong><em>Men det ødelegger faktisk prestasjonen din.</em></p><hr><h2 id="lysbilde-9-sparke-kritikeren-din-ansett-coachen-din-🔄" tabindex="-1">Lysbilde 9: Sparke kritikeren din, ansett coachen din! 🔄 <a class="header-anchor" href="#lysbilde-9-sparke-kritikeren-din-ansett-coachen-din-🔄" aria-label="Permalink to &quot;Lysbilde 9: Sparke kritikeren din, ansett coachen din! 🔄&quot;">​</a></h2><h3 id="transformasjonen" tabindex="-1">Transformasjonen: <a class="header-anchor" href="#transformasjonen" aria-label="Permalink to &quot;Transformasjonen:&quot;">​</a></h3><p>| 😈 Indre kritiker | ➡️ | 😊 Indre coach | |----------------| ...| | &quot;Du roter ALLTID til noe!&quot; | → | &quot;Jeg har tatt dette bildet 1000 ganger før&quot; | | &quot;Det var FORFERDELIG!&quot; | → | &quot;Hva kan jeg lære av dette?&quot; | | &quot;Alle dømmer deg!&quot; | → | &quot;Fokuser på MITT spill, ikke meningene deres&quot; | | &quot;Du er ikke god nok!&quot; | → | &quot;Jeg blir bedre hver dag&quot; |</p><h3 id="virkningen" tabindex="-1">Virkningen: <a class="header-anchor" href="#virkningen" aria-label="Permalink to &quot;Virkningen:&quot;">​</a></h3><p><strong>Kritiker = Angst, spenning, dårlig prestasjon</strong><strong>Coach = Selvtillit, avslapning, topp ytelse</strong></p><hr><h2 id="lysbilde-10-aktivitet-–-omformuler-kritikeren-din-💬" tabindex="-1">Lysbilde 10: AKTIVITET – Omformuler kritikeren din! 💬 <a class="header-anchor" href="#lysbilde-10-aktivitet-–-omformuler-kritikeren-din-💬" aria-label="Permalink to &quot;Lysbilde 10: AKTIVITET – Omformuler kritikeren din! 💬&quot;">​</a></h2><h3 id="partnerøvelse-3-minutter" tabindex="-1">Partnerøvelse (3 minutter) <a class="header-anchor" href="#partnerøvelse-3-minutter" aria-label="Permalink to &quot;Partnerøvelse (3 minutter)&quot;">​</a></h3><p><strong>Snu deg til personen ved siden av deg:</strong></p><p><strong>Person A (1,5 min):</strong></p><ol><li>Del én ting din indre kritiker sier</li><li>Partner hjelper deg med å omformulere det som indre coach</li><li>Skriv ned den nye frasen</li></ol><p><strong>Person B (1,5 min):</strong></p><ol><li>Samme prosess</li><li>Del din indre kritiker-tanke</li><li>Få hjelp til å endre formuleringen</li></ol><p><strong>Klar? Kjør!</strong></p><p><em>Vi deler noen eksempler med gruppen etterpå...</em></p><hr><h2 id="lysbilde-11-verktøy-nr-1-–-3-pustetilbakestillingen-🌬️" tabindex="-1">Lysbilde 11: Verktøy nr. 1 – 3-pustetilbakestillingen 🌬️ <a class="header-anchor" href="#lysbilde-11-verktøy-nr-1-–-3-pustetilbakestillingen-🌬️" aria-label="Permalink to &quot;Lysbilde 11: Verktøy nr. 1 – 3-pustetilbakestillingen 🌬️&quot;">​</a></h2><h3 id="din-nødtrykkavlastningsventil" tabindex="-1">Din nødtrykkavlastningsventil <a class="header-anchor" href="#din-nødtrykkavlastningsventil" aria-label="Permalink to &quot;Din nødtrykkavlastningsventil&quot;">​</a></h3><p><strong>Bruk dette når:</strong></p><ul><li>😤 Du gjorde nettopp en feil</li><li>😰 Du føler presset bygger seg opp</li><li>🤯 Tankene dine raser</li></ul><h3 id="prosessen-1" tabindex="-1">Prosessen: <a class="header-anchor" href="#prosessen-1" aria-label="Permalink to &quot;Prosessen:&quot;">​</a></h3><p><strong>🌬️ PUST 1 (Innpust 4 sek):</strong> Legg merke til hvor du føler spenning (skuldre? kjeve? mage?)</p><p><strong>🌬️ PUST 2 (Pust ut i 6 sekunder):</strong> Slipp spenningen. La den flyte ut med pusten din.</p><p><strong>🌬️ PUST 3 (Innpust 4, Pust ut 6):</strong> Fokuser på NÅ. Dette bildet. Dette øyeblikket. Ingenting annet.</p><p><strong>⏱️ Tar 20 sekunder. Endrer alt.</strong></p><hr><h2 id="lysbilde-12-demo-–-alle-ma-prøve-det-🌬️" tabindex="-1">Lysbilde 12: DEMO – Alle må prøve det! 🌬️ <a class="header-anchor" href="#lysbilde-12-demo-–-alle-ma-prøve-det-🌬️" aria-label="Permalink to &quot;Lysbilde 12: DEMO – Alle må prøve det! 🌬️&quot;">​</a></h2><h3 id="_3-pusteøvelse-1-minutt" tabindex="-1">3-pusteøvelse (1 minutt) <a class="header-anchor" href="#_3-pusteøvelse-1-minutt" aria-label="Permalink to &quot;3-pusteøvelse (1 minutt)&quot;">​</a></h3><p><strong>Alle sammen, lukk øynene...</strong></p><p><strong>Pustegang 1:</strong><em>Pust inn i 4 sekunder... Hvor føler du spenningen?</em></p><p><strong>Pustegang 2:</strong><em>Pust ut i 6 sekunder... Slipp det løs...</em></p><p><strong>Pustegang 3:</strong><em>Inn for 4, ut for 6... Kun nåtiden...</em></p><p><strong>Åpne øynene. Hvordan føler du deg?</strong></p><p><em>Dette er tilbakestillingsknappen din. Bruk den!</em></p><hr><h2 id="lysbilde-13-verktøy-nr-2-–-din-rutine-før-fotografering-🎯" tabindex="-1">Lysbilde 13: Verktøy nr. 2 – Din rutine før fotografering 🎯 <a class="header-anchor" href="#lysbilde-13-verktøy-nr-2-–-din-rutine-før-fotografering-🎯" aria-label="Permalink to &quot;Lysbilde 13: Verktøy nr. 2 – Din rutine før fotografering 🎯&quot;">​</a></h2><h3 id="bygg-automatisk-konsistens" tabindex="-1">Bygg automatisk konsistens <a class="header-anchor" href="#bygg-automatisk-konsistens" aria-label="Permalink to &quot;Bygg automatisk konsistens&quot;">​</a></h3><p><strong>4-trinnsrutinen:</strong></p><p><strong>1️⃣ VISUALISER (3 sekunder)</strong> Se det perfekte bildet for deg. Se det lande akkurat der du vil.</p><p><strong>2️⃣ PUST (2 sekunder)</strong> Ett dypt åndedrag. Bytt fra planleggings- til utførelsesmodus.</p><p><strong>3️⃣ ANKER (2 sekunder)</strong> Berør boulen din. Føl vekten. Fysisk forbindelse.</p><p><strong>4️⃣ UTFØR (2 sekunder)</strong> Stol helt på deg selv. La kroppen din gjøre det den vet.</p><p><strong>⏱️ Totalt: 9 sekunder. Samme hver gang.</strong></p><h3 id="hvorfor-det-fungerer" tabindex="-1">Hvorfor det fungerer: <a class="header-anchor" href="#hvorfor-det-fungerer" aria-label="Permalink to &quot;Hvorfor det fungerer:&quot;">​</a></h3><p><strong>Konsistens = Tillit = Ytelse</strong></p><hr><h2 id="lysbilde-14-verktøy-nr-3-–-protokoll-for-feilgjenoppretting-🔄" tabindex="-1">Lysbilde 14: Verktøy nr. 3 – Protokoll for feilgjenoppretting 🔄 <a class="header-anchor" href="#lysbilde-14-verktøy-nr-3-–-protokoll-for-feilgjenoppretting-🔄" aria-label="Permalink to &quot;Lysbilde 14: Verktøy nr. 3 – Protokoll for feilgjenoppretting 🔄&quot;">​</a></h2><h3 id="darlig-skudd-her-er-din-4-trinns-gjenoppretting" tabindex="-1">Dårlig skudd? Her er din 4-trinns gjenoppretting: <a class="header-anchor" href="#darlig-skudd-her-er-din-4-trinns-gjenoppretting" aria-label="Permalink to &quot;Dårlig skudd? Her er din 4-trinns gjenoppretting:&quot;">​</a></h3><p><strong>1️⃣ BEKREFTEN (2 sekunder)</strong> «Det gikk ikke som planlagt.» (Ingen fordømmelse, bare fakta)</p><p><strong>2️⃣ SLIP (3 sekunder)</strong> Fysisk tilbakestilling: Håndhilste, rull med skuldrene, gå 3 skritt.</p><p><strong>3️⃣ REFOKUSÉR (3 sekunder)</strong> «Neste sjanse er en NY mulighet.» (Ikke knyttet til den forrige)</p><p><strong>4️⃣ UTFØR (Bruk rutinen din)</strong> Stol på rutinen din før du sprøyter. En ny start.</p><h3 id="den-viktigste-innsikten" tabindex="-1">Den viktigste innsikten: <a class="header-anchor" href="#den-viktigste-innsikten" aria-label="Permalink to &quot;Den viktigste innsikten:&quot;">​</a></h3><p><strong>Hvert skudd er uavhengig. Ikke overfør feilene dine videre.</strong></p><p><em>De beste spillerne har kortest hukommelse for dårlige skudd.</em></p><hr><h2 id="lysbilde-15-ærlig-snakk-–-hva-stopper-deg-💬" tabindex="-1">Lysbilde 15: ÆRLIG SNAKK – Hva stopper deg? 💬 <a class="header-anchor" href="#lysbilde-15-ærlig-snakk-–-hva-stopper-deg-💬" aria-label="Permalink to &quot;Lysbilde 15: ÆRLIG SNAKK – Hva stopper deg? 💬&quot;">​</a></h2><h3 id="gruppediskusjon-5-minutter" tabindex="-1">Gruppediskusjon (5 minutter) <a class="header-anchor" href="#gruppediskusjon-5-minutter" aria-label="Permalink to &quot;Gruppediskusjon (5 minutter)&quot;">​</a></h3><p><strong>La oss høre fra deg:</strong></p><p><strong>Spørsmål 1:</strong><em>&quot;Når føler du deg MEST i flyt? Hvilke forhold hjelper?&quot;</em></p><p><strong>Spørsmål 2:</strong><em>&quot;Hva er din største mentale utfordring i konkurranse?&quot;</em></p><p><strong>Spørsmål 3:</strong><em>&quot;Hvilket av disse verktøyene gir deg mest gjenklang?&quot;</em></p><ul><li>3-pust-tilbakestilling</li><li>Rutine før inntak</li><li>Indre coach-omformulering</li><li>Gjenoppretting av feil</li></ul><p><strong>Del åpent – dette er et trygt sted!</strong></p><hr><h2 id="lysbilde-16-handlingsplanen-din-–-velg-en-✅" tabindex="-1">Lysbilde 16: Handlingsplanen din – velg ÉN! ✅ <a class="header-anchor" href="#lysbilde-16-handlingsplanen-din-–-velg-en-✅" aria-label="Permalink to &quot;Lysbilde 16: Handlingsplanen din – velg ÉN! ✅&quot;">​</a></h2><h3 id="denne-ukens-utfordring" tabindex="-1">Denne ukens utfordring: <a class="header-anchor" href="#denne-ukens-utfordring" aria-label="Permalink to &quot;Denne ukens utfordring:&quot;">​</a></h3><p><strong>Velg KUN ÉN teknikk å øve på:</strong></p><p><strong>Alternativ A: 🌬️ 3-pustetilbakestilling</strong> Bruk etter HVER feil i treningen</p><p><strong>Alternativ B: 🎯 Rutine før inntak</strong> Samme 4-trinnsrutine på HVERT kast</p><p><strong>Alternativ C: 💬 Indre coach</strong> Omformuler ÉN kritisk tanke per økt</p><p><strong>Alternativ D: 🔄 Modusbytte</strong> Øvelsesplanlegging → utførelsesbryter</p><h3 id="hvorfor-bare-en" tabindex="-1">Hvorfor bare én? <a class="header-anchor" href="#hvorfor-bare-en" aria-label="Permalink to &quot;Hvorfor bare én?&quot;">​</a></h3><p><strong>Mestre ett verktøy før du legger til et annet.</strong><em>Dybde slår bredde i mental trening.</em></p><hr><h2 id="lysbilde-17-spor-fremgangen-din-📊" tabindex="-1">Lysbilde 17: Spor fremgangen din 📊 <a class="header-anchor" href="#lysbilde-17-spor-fremgangen-din-📊" aria-label="Permalink to &quot;Lysbilde 17: Spor fremgangen din 📊&quot;">​</a></h2><h3 id="hva-du-bør-legge-merke-til-denne-uken" tabindex="-1">Hva du bør legge merke til denne uken: <a class="header-anchor" href="#hva-du-bør-legge-merke-til-denne-uken" aria-label="Permalink to &quot;Hva du bør legge merke til denne uken:&quot;">​</a></h3><p><strong>🎯 Flytøyeblikk:</strong></p><ul><li>Når følte du deg «i sonen»?</li><li>Hvilken tid på dagen?</li><li>Hvilken type skudd?</li><li>Hva hjalp deg med å komme dit?</li></ul><p><strong>💪 Teknikksuksess:</strong></p><ul><li>Hvilket verktøy fungerte best?</li><li>Når brukte du den?</li><li>Hva ble resultatet?</li></ul><p><strong>📝 Før en enkel logg:</strong><em>&quot;Brukte 3-pustet tilbakestilling etter feil → følte meg roligere → tok neste skudd&quot;</em></p><h3 id="malet" tabindex="-1">Målet: <a class="header-anchor" href="#malet" aria-label="Permalink to &quot;Målet:&quot;">​</a></h3><p><strong>Finn DINE mønstre. Bygg DITT system.</strong></p><hr><h2 id="lysbilde-18-fortsett-reisen-din-🚀" tabindex="-1">Lysbilde 18: Fortsett reisen din 🚀 <a class="header-anchor" href="#lysbilde-18-fortsett-reisen-din-🚀" aria-label="Permalink to &quot;Lysbilde 18: Fortsett reisen din 🚀&quot;">​</a></h2><h3 id="gratis-ressurser-pa-carreau-app" tabindex="-1">Gratis ressurser på carreau.app: <a class="header-anchor" href="#gratis-ressurser-pa-carreau-app" aria-label="Permalink to &quot;Gratis ressurser på carreau.app:&quot;">​</a></h3><p><strong>📚 Dypdykk:</strong></p><ul><li><strong>Sonen</strong> – Hovedstrømningstilstander</li><li><strong>Mental styrke</strong> - Avansert presshåndtering</li><li><strong>Teamdynamikk</strong> - Kommunikasjon og tillit</li><li><strong>Mindfulness</strong> - Fokus i nåtiden</li></ul><p><strong>🛠️ Praktiske verktøy:</strong></p><ul><li><strong>Målmal</strong> – Strukturer utviklingen din</li><li><strong>Dagbokmal</strong> – Spor daglig fremgang</li><li><strong>Workshop-guide</strong> – Kjør dine egne økter</li></ul><p><strong>Alt gratis. Alt tilgjengelig. Alt designet for elitespillere.</strong></p><hr><h2 id="lysbilde-19-de-4-store-ideene-💡" tabindex="-1">Lysbilde 19: De 4 store ideene 💡 <a class="header-anchor" href="#lysbilde-19-de-4-store-ideene-💡" aria-label="Permalink to &quot;Lysbilde 19: De 4 store ideene 💡&quot;">​</a></h2><h3 id="ta-disse-med-hjem" tabindex="-1">Ta disse med hjem: <a class="header-anchor" href="#ta-disse-med-hjem" aria-label="Permalink to &quot;Ta disse med hjem:&quot;">​</a></h3><p><strong>1️⃣ Flyt er en FERDIGHET, ikke flaks</strong> Du kan lære å få tilgang til den på forespørsel</p><p><strong>2️⃣ Din indre stemme FORMER prestasjonen din</strong> Tren deg selv, ikke kritiser deg selv</p><p><strong>3️⃣ Enkle verktøy ARBEIDER under press</strong> 3 åndedrag. En rutine. En tilbakestilling. Det er alt.</p><p><strong>4️⃣ Øvelse gjør varig</strong> Mentale ferdigheter trenger trening, i likhet med tekniske ferdigheter</p><h3 id="sannheten-1" tabindex="-1">Sannheten: <a class="header-anchor" href="#sannheten-1" aria-label="Permalink to &quot;Sannheten:&quot;">​</a></h3><p><strong>Mental trening er ikke mystisk. Det er praktisk.</strong></p><hr><h2 id="lysbilde-20-spørsmal-la-oss-snakke-💬" tabindex="-1">Lysbilde 20: Spørsmål? La oss snakke! 💬 <a class="header-anchor" href="#lysbilde-20-spørsmal-la-oss-snakke-💬" aria-label="Permalink to &quot;Lysbilde 20: Spørsmål? La oss snakke! 💬&quot;">​</a></h2><h1 id="apen-diskusjon" tabindex="-1">Åpen diskusjon <a class="header-anchor" href="#apen-diskusjon" aria-label="Permalink to &quot;Åpen diskusjon&quot;">​</a></h1><p><strong>Hvilke spørsmål har du?</strong></p><p><strong>Hvilke erfaringer vil du dele?</strong></p><p><strong>Hvilke utfordringer står du overfor?</strong></p><p><strong>Hva vil du prøve først?</strong></p><p><em>Dette er DIN økt. La oss gjøre den verdifull for DEG.</em></p><hr><h2 id="lysbilde-21-din-utfordring-🎯" tabindex="-1">Lysbilde 21: Din utfordring 🎯 <a class="header-anchor" href="#lysbilde-21-din-utfordring-🎯" aria-label="Permalink to &quot;Lysbilde 21: Din utfordring 🎯&quot;">​</a></h2><h1 id="denne-ukens-oppdrag" tabindex="-1">Denne ukens oppdrag: <a class="header-anchor" href="#denne-ukens-oppdrag" aria-label="Permalink to &quot;Denne ukens oppdrag:&quot;">​</a></h1><p><strong>1️⃣ Velg ETT verktøy</strong> (3-pust-tilbakestilling, rutine før skudd, indre coach eller modusbytte)</p><p><strong>2️⃣ Øv på det HVER økt</strong> (Konsistens slår intensitet)</p><p><strong>3️⃣ Legg merke til hva som endres</strong> (Spor fremgangen din)</p><p><strong>4️⃣ Del resultatene dine</strong> (Med treningspartnerne dine eller på carreau.app)</p><h3 id="huske" tabindex="-1">Huske: <a class="header-anchor" href="#huske" aria-label="Permalink to &quot;Huske:&quot;">​</a></h3><p><strong>Små endringer → Store resultater</strong></p><hr><h2 id="lysbilde-22-takk-🙏" tabindex="-1">Lysbilde 22: Takk! 🙏 <a class="header-anchor" href="#lysbilde-22-takk-🙏" aria-label="Permalink to &quot;Lysbilde 22: Takk! 🙏&quot;">​</a></h2><h1 id="du-har-fatt-dette" tabindex="-1">Du har fått dette! <a class="header-anchor" href="#du-har-fatt-dette" aria-label="Permalink to &quot;Du har fått dette!&quot;">​</a></h1><p><strong>Hva du lærte i dag:</strong></p><ul><li>✅ Slik får du tilgang til flyttilstander</li><li>✅ Hvordan håndtere din indre kritiker</li><li>✅ Praktiske verktøy som fungerer under press</li><li>✅ En tydelig handlingsplan for denne uken</li></ul><p><strong>Neste trinn:</strong></p><ol><li>Velg din ÉNE teknikk</li><li>Øv det konsekvent</li><li>Besøk carreau.app for flere ressurser</li><li>Del fremgangen din med gruppen</li></ol><h3 id="reisen-starter-na" tabindex="-1">Reisen starter nå: <a class="header-anchor" href="#reisen-starter-na" aria-label="Permalink to &quot;Reisen starter nå:&quot;">​</a></h3><p><strong>Mental trening er praktisk, ikke mystisk.</strong><strong>Start i dag. Se resultater snart.</strong></p><hr><p><em>Pétanque Academy - Elitespillerutvikling</em><em>carreau.app – Gratis ressurser for elitespillere</em></p>',201)])])}]]);export{i as __pageData,a as default};
